"""Formatting for json.loads

    Args:
        str_dict (str): str containing dict of spead streams (received on ?configure).

    Returns:
        str_dict (str): str containing dict of spead streams, formatted for use with json.loads
    """
def json_str_formatter(str_dict: Any) -> object {
    str_dict = str_dict.replace('\'', '"');
    str_dict = str_dict.replace('', '');
    return str_dict;
}

test_blocks:
test "t0" {
    assert (
        json_str_formatter('{"1":{"2":{"3":4}},"4":5}') == '{"1":{"2":{"3":4}},"4":5}'
    );;
}

test "t1" {
    assert (
        json_str_formatter(
            r'{"streams": [{"stream_id": 0, "format": "cf32", "shape": [16, 16]}]}'
        )
        == r'{"streams": [{"stream_id": 0, "format": "cf32", "shape": [16, 16]}]}'
    );;
}

